            if (!text) return `post-${Date.now()}`;
            return text.toString().toLowerCase().trim()
                .replace(/\s+/g, '-')
                .replace(/[^\w\-]+/g, '')
                .replace(/\-\-+/g, '-');
        };

        let finalSlug = currentBlog.slug;
        if (!finalSlug || finalSlug.trim() === '') {
            finalSlug = generateSlug(currentBlog.title || `blog-${Date.now()}`);
        }

