                                    const formattedKw = kw.trim().replace(/\s+/g, ',');
                                    setCurrentBlog({
                                        ...currentBlog, 
                                        stock_keywords: kw,
                                        image: kw ? `https://loremflickr.com/1280/800/${encodeURIComponent(formattedKw)}` : currentBlog.image
                                    });
